<?= $this->extend('layouts/auth') ?><?= $this->section('content') ?><h1 class="text-center fs-4">Buat akun baru</h1><form action="<?= site_url('register') ?>" method="post"><?= csrf_field() ?><?php foreach(['name'=>['Nama Lengkap','text','name'],'email'=>['Email','email','email'],'phone'=>['Nomor Telepon','tel','tel']] as $field=>[$label,$type,$autocomplete]): ?><label class="form-label" for="<?= $field ?>"><?= $label ?></label><input class="form-control" id="<?= $field ?>" name="<?= $field ?>" type="<?= $type ?>" autocomplete="<?= $autocomplete ?>" <?= $field!=='phone'?'required':'' ?> value="<?= esc($values[$field]??'','attr') ?>"><?php endforeach ?><label class="form-label" for="address">Alamat</label><textarea class="form-control" id="address" name="address" maxlength="300" autocomplete="street-address" rows="2"><?= esc($values['address']??'') ?></textarea><label class="form-label" for="password">Password (minimal 8 karakter)</label><input class="form-control" type="password" name="password" id="password" minlength="8" maxlength="72" autocomplete="new-password" required><label class="form-label" for="password_confirm">Konfirmasi Password</label><input class="form-control" type="password" name="password_confirm" id="password_confirm" minlength="8" maxlength="72" autocomplete="new-password" required><button class="btn btn-primary w-100 mt-2">Daftar</button></form><p class="auth-bottom">Sudah punya akun? <a href="<?= site_url('login') ?>">Login</a></p><?= $this->endSection() ?>